void lf_off( void *arg )
{
    if( !os_pip_insert( lf_pip , LF_CMD_OFF , LF_PIP_INSERT_TIMEOUT )  )
    {
        os_pip_flush( lf_pip ) ;            	

        os_pip_insert( lf_pip , LF_CMD_OFF , LF_PIP_INSERT_TIMEOUT ) ;         

        TRACE_LF("\n\r[LF_CMD_OFF_FLUSH]\n\r");      
    }    
}		

